newsrc='''import collections

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = collections.Counter(v for row in g for v in row).most_common(1)[0][0]

    def edge_run(values):
        runs = []
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j-i >= 2:
                runs.append((i, j-1, values[i]))
            i = j
        return max(runs, key=lambda x: x[1]-x[0]) if runs else None

    # The task uses equal-width guide bars on opposite edges, either horizontal or vertical.
    candidates = []
    a, b = edge_run(g[0]), edge_run(g[-1])
    if a and b and a[2] == b[2]:
        candidates.append(('h', a, b, a[2]))
    a = edge_run([g[r][0] for r in range(h)])
    b = edge_run([g[r][-1] for r in range(h)])
    if a and b and a[2] == b[2]:
        candidates.append(('v', a, b, a[2]))
    if not candidates:
        return g

    chosen = None
    for orient, first, last, guide in candidates:
        markers = [(r,c,g[r][c]) for r in range(h) for c in range(w)
                   if g[r][c] != bg and g[r][c] != guide]
        if not markers:
            continue
        lo1, hi1 = first[0], first[1]
        lo2, hi2 = last[0], last[1]
        coord = (lambda r,c: c) if orient == 'h' else (lambda r,c: r)
        coords = [coord(r,c) for r,c,_ in markers]
        in_first = all(lo1 <= x <= hi1 for x in coords)
        in_last = all(lo2 <= x <= hi2 for x in coords)
        score = sum(lo1 <= x <= hi1 or lo2 <= x <= hi2 for x in coords)
        if in_first and not in_last:
            side = 'first'
        elif in_last and not in_first:
            side = 'last'
        elif in_first:
            side = 'first'
        else:
            side = None
        rank = (int(side is not None), score, len(markers))
        if side is not None and (chosen is None or rank > chosen[0]):
            chosen = (rank, orient, first, last, guide, markers, side)
    if chosen is None:
        return g
    _, orient, first, last, guide, markers, side = chosen
    src, dst = (first, last) if side == 'first' else (last, first)
    width = min(src[1]-src[0]+1, dst[1]-dst[0]+1)
    axis_len = w if orient == 'h' else h

    for r, c, color in markers:
        pos = c if orient == 'h' else r
        local = pos-src[0]
        if not 0 <= local < width:
            continue
        dest_pos = dst[0] + local
        # Copy each marked lane across the full field on the opposite side.
        for k in range(h if orient == 'h' else w):
            rr, cc = (k, dest_pos) if orient == 'h' else (dest_pos, k)
            if g[rr][cc] != guide:
                g[rr][cc] = color

        # Colors 0 and 6 also connect back to their own guide edge.
        # Color 7 is copied only to the opposite lane.
        if color != 7:
            if orient == 'h':
                if side == 'first':
                    path = range(1, r)
                    for rr in path:
                        if g[rr][c] != guide: g[rr][c] = color
                else:
                    for rr in range(r+1, h-1):
                        if g[rr][c] != guide: g[rr][c] = color
            else:
                if side == 'first':
                    for cc in range(1, c):
                        if g[r][cc] != guide: g[r][cc] = color
                else:
                    for cc in range(c+1, w-1):
                        if g[r][cc] != guide: g[r][cc] = color
        g[r][c] = 4
    return g
'''
